/**
 * Legal documents published on /legal (HTML) and as PDFs (public/legal/<slug>.pdf, generated by
 * scripts/build-legal-pdfs.mjs). Generic broker wording; the company name is injected at render time.
 * `{{COMPANY}}` is replaced with the brand name.
 */
export interface LegalSection {
  h: string;
  p: string[];
}
export interface LegalDoc {
  slug: string;
  title: string;
  group: 'Agreement' | 'Risk' | 'Compliance' | 'Costs' | 'Trading' | 'Data' | 'Promotions';
  note: string;
  version: string;
  effective: string;
  sections: LegalSection[];
}

